CREATE TABLE sre_metadata(version INTEGER NOT NULL, migration_hash TEXT NOT NULL);
CREATE TABLE sre_services(tenant TEXT NOT NULL, app TEXT NOT NULL, id TEXT NOT NULL, document TEXT NOT NULL, digest TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), PRIMARY KEY(tenant,app,id));
CREATE TABLE sre_observations(tenant TEXT NOT NULL, app TEXT NOT NULL, id TEXT NOT NULL, service TEXT NOT NULL, source_time TEXT NOT NULL, ingested_at TEXT NOT NULL, document TEXT NOT NULL, digest TEXT NOT NULL, PRIMARY KEY(tenant,app,id), FOREIGN KEY(tenant,app,service) REFERENCES sre_services(tenant,app,id));
CREATE TABLE sre_validations(tenant TEXT NOT NULL, app TEXT NOT NULL, id TEXT NOT NULL, document TEXT NOT NULL, digest TEXT NOT NULL, PRIMARY KEY(tenant,app,id), FOREIGN KEY(tenant,app,id) REFERENCES sre_observations(tenant,app,id));
CREATE TABLE sre_dependencies(tenant TEXT NOT NULL, app TEXT NOT NULL, id TEXT NOT NULL, source TEXT NOT NULL, dependent TEXT NOT NULL, document TEXT NOT NULL, digest TEXT NOT NULL, PRIMARY KEY(tenant,app,id), UNIQUE(tenant,app,source,dependent), FOREIGN KEY(tenant,app,source) REFERENCES sre_services(tenant,app,id), FOREIGN KEY(tenant,app,dependent) REFERENCES sre_services(tenant,app,id));
CREATE TABLE sre_incidents(tenant TEXT NOT NULL, app TEXT NOT NULL, id TEXT NOT NULL, service TEXT NOT NULL, document TEXT NOT NULL, digest TEXT NOT NULL, PRIMARY KEY(tenant,app,id), FOREIGN KEY(tenant,app,service) REFERENCES sre_services(tenant,app,id));
CREATE TABLE sre_audit(tenant TEXT NOT NULL, app TEXT NOT NULL, sequence INTEGER NOT NULL, document TEXT NOT NULL, digest TEXT NOT NULL, PRIMARY KEY(tenant,app,sequence));
